      "keystrokes": "cat > ocr_screen.py << 'EOF'
import pytesseract
from PIL import Image
import json

# Open the screen capture
img = Image.open('screen_capture.png')

# Perform OCR with data output to get bounding boxes
data = pytesseract.image_to_data(img, output_type=pytesseract.Output.DICT)

# Also try with Chinese language support
try:
    data_cn = pytesseract.image_to_data(img, lang='eng+chi_sim', output_type=pytesseract.Output.DICT)
except:
    data_cn = data

# Parse results and filter for readable text (confidence > 50)
text_items = []
for i in range(len(data['text'])):
    text = data['text'][i].strip()
    if text and int(data['conf'][i]) > 50:
        # Calculate center coordinates
        x = int(data['left'][i]) + int(data['width'][i]) / 2
        y = int(data['top'][i]) + int(data['height'][i]) / 2

        # Check if text is related to confirmation dialog
        # Include: dialog title, file names, warnings, buttons, codes
        text_lower = text.lower()
        if any(kw in text_lower for kw in ['confirm', 'delete', 'file:', 'cannot', 'undone', 'code:', 'zx-', 'cancel', '取消']):
            if text not in [t['text'] for t in text_items]:
                text_items.append({
                    'text': text,
                    'x': x,
                    'y': y,
                    'confidence': int(data['conf'][i])
                })

# Also check Chinese text from the Chinese-enabled OCR
for i in range(len(data_cn['text'])):
    text = data_cn['text'][i].strip()
    if text and int(data_cn['conf'][i]) > 50:
        # Check for Chinese characters
        if any('\u4e00' <= c <= '\u9fff' for c in text):
            x = int(data_cn['left'][i]) + int(data_cn['width'][i]) / 2
            y = int(data_cn['top'][i]) + int(data_cn['height'][i]) / 2
            if text not in [t['text'] for t in text_items]:
                text_items.append({
                    'text': text,
                    'x': x,
                    'y': y,
                    'confidence': int(data_cn['conf'][i])
                })

# Save to JSON
with open('screen_text_map.json', 'w', encoding='utf-8') as f:
    json.dump(text_items, f, ensure_ascii=False, indent=2)

print(f"Extracted {len(text_items)} text items")
for item in text_items:
    print(f"  {item['text']}: ({item['x']}, {item['y']})")
EOF\n",
      "duration": 0.5
    },
    {
      "keystrokes": "python3 ocr_screen.py\n",
      "duration": 5
    }
